/* ---------- Source stack ---------- */
/* everything the agent read, folded into one pill under the answer: the first sources' marks side by side (never stacked
   over each other, owner, 18 Nov) and the count. Open, a filter and the list: each source's mark, its title and where it
   came from, how much it counted, and a button to open it. A mark is a vivid fill of its own with white letters (or an
   avatar colour with its own ink); Clean keeps its marks one neutral grey. It sits on the stage, not on a card, so a row's
   hover fill is a quiet step darker than the stage (owner, 18 Nov), reaching out round the row's mark and words */
.ssx{display:flex;flex-direction:column;gap:10px;align-items:flex-start;--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.ssx-pill{display:inline-flex;align-items:center;gap:var(--dm-s-2);height:30px;padding:0 10px 0 6px;border-radius:var(--dm-r-pill);background:var(--dm-chip);font-size:12.5px;color:var(--dm-fg2);transition:background .25s,color .25s}
@media (hover:hover) and (pointer:fine){.ssx-pill:hover{background:var(--dm-hover);color:var(--dm-fg)}}
.ssx-pill>svg{transition:transform .4s var(--dm-ease)}
.ssx-pill[aria-expanded="true"]>svg{transform:rotate(180deg)}
.ssx-ics{display:flex;gap:2px}
.ssx-ics span{width:18px;height:18px;border-radius:50%;display:grid;place-items:center;font-size:9px;font-weight:500;color:#fff}
.ssx-box{width:100%}
.ssx-in{padding:2px 0 var(--dm-s-1);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.ssx-fl{display:flex;gap:var(--dm-s-2);flex-wrap:wrap}
/* the filters are white chips with a dimmed grey edge; the picked one's edge is a step stronger */
.ssx-fl .chip{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent)}
@media (hover:hover) and (pointer:fine){.ssx-fl .chip:hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-faint) 50%,transparent)}}
.ssx-list{display:flex;flex-direction:column;gap:2px;margin-inline:-6px}
.ssx-s{display:flex;align-items:center;gap:10px;padding:7px 6px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;transition:background .25s}
@media (hover:hover) and (pointer:fine){.ssx-s:hover{background:var(--dm-row)}}
.ssx-s .fv{width:22px;height:22px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;font-size:9.5px;font-weight:500;color:#fff;flex:none}
.ssx-s .t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ssx-s .h{font-size:12px;color:var(--dm-muted)}
.ssx-s .rel{width:36px;height:4px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-line);overflow:hidden;flex:none}
.ssx-s .rel i{display:block;height:100%;background:var(--dm-accent-mark,var(--dm-accent));border-radius:var(--dm-r-tiny,2px);transform-origin:left;animation:ssrel .8s var(--dm-ease) both}
@keyframes ssrel{from{transform:scaleX(0)}}
.ssx-s .ib{width:24px;height:24px;opacity:0;transition:opacity .2s}
@media (hover:hover) and (pointer:fine){.ssx-s:hover .ib{opacity:1}}
.ssx-s .ib:focus-visible{opacity:1}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.ssx :is(.ib,.pill):active,:root[data-style="clean"] .ssx .ib:active,:root [data-style="clean"] .ssx .ib:active,:root [data-style="clean"].ssx .ib:active{transform:none}
/* Clean (owner, 18 Nov): the sources' marks are one neutral grey with a hairline, not a colour each */
:root[data-style="clean"] :is(.ssx-ics span,.ssx-s .fv),:root [data-style="clean"] :is(.ssx-ics span,.ssx-s .fv),:root [data-style="clean"]:is(.ssx-ics span,.ssx-s .fv){background:var(--dm-chip)!important;color:var(--dm-fg2)!important;box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .ssx-s,:root [data-style="clean"] .ssx-s,:root [data-style="clean"].ssx-s{border-radius:var(--dm-r-in)}
/* the filter chips keep their quiet edge: the one hover fills them, and the picked one has the stronger fill (owner, 21 Nov:
   never a stronger edge); the sources pill deepens by the same fill, and holds the stronger one while its list is open
   (Agent harness keeps its own) */
:root[data-style="clean"] .ssx-fl .chip,:root [data-style="clean"] .ssx-fl .chip,:root [data-style="clean"].ssx-fl .chip{transition:background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ssx-fl .chip:not(.on):hover,:root [data-style="clean"] .ssx-fl .chip:not(.on):hover,:root [data-style="clean"].ssx-fl .chip:not(.on):hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),inset 0 0 0 99px var(--dm-row)}}
:root[data-style="clean"] .ssx-fl .chip.on,:root [data-style="clean"] .ssx-fl .chip.on,:root [data-style="clean"].ssx-fl .chip.on{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),inset 0 0 0 99px var(--dm-row-on)}
:root[data-style="clean"] .ssx-pill:not(.ahx *),:root [data-style="clean"] .ssx-pill:not(.ahx *),:root [data-style="clean"].ssx-pill:not(.ahx *){box-shadow:inset 0 0 0 99px transparent}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ssx-pill:not(.ahx *):hover,:root [data-style="clean"] .ssx-pill:not(.ahx *):hover,:root [data-style="clean"].ssx-pill:not(.ahx *):hover{background:var(--dm-chip);box-shadow:inset 0 0 0 99px var(--dm-row)}}
:root[data-style="clean"] .ssx-pill:not(.ahx *)[aria-expanded="true"],:root [data-style="clean"] .ssx-pill:not(.ahx *)[aria-expanded="true"],:root [data-style="clean"].ssx-pill:not(.ahx *)[aria-expanded="true"]{box-shadow:inset 0 0 0 99px var(--dm-row-on)}
:root[data-style="clean"] :is(.ssx-pill,.ssx-s,.ssx-s .ib),:root [data-style="clean"] :is(.ssx-pill,.ssx-s,.ssx-s .ib),:root [data-style="clean"]:is(.ssx-pill,.ssx-s,.ssx-s .ib){transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease)}

DM.def('source-stack', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs'));
  const S = [
    ['web','Baymard: pricing page UX','baymard.com',.92,'B','var(--dm-av-b)'],
    ['web','Annual vs monthly anchoring study','cxl.com',.88,'C','var(--dm-av-r)'],
    ['file','Q3 conversion export.csv','Drive',.84,'CSV','var(--dm-av-m)'],
    ['figma','Pricing v4, frame 2','Figma',.8,'F','var(--dm-av-l)'],
    ['web','Stripe billing docs','stripe.com',.66,'S','var(--dm-av-k)'],
    ['file','Pricing research notes','Notion',.61,'N','var(--dm-av-t)'],
    ['figma','Checkout flow','Figma',.52,'F','var(--dm-av-l)'],
    ['web','NN/g on price framing','nngroup.com',.48,'N','var(--dm-av-y)']
  ];
  // each source's mark on its own vivid fill, with that fill's ink: white, or a dark ink of its hue where white would fail
  const ink = col => col.replace(')', '-ink)');
  const pill = $('.ssx-pill', r), box = $('.ssx-box', r), list = $('.ssx-list', r);
  if (!r.closest('.ahx')) c.offs.push(hoverGlide(list, '.ssx-s'));
  $('.ssx-ics', r).innerHTML = S.slice(0, 4).map(s => `<span style="background:${s[5]};color:${ink(s[5])}">${s[4][0]}</span>`).join('');
  function paint(f){
    const items = S.filter(s => f === 'all' || s[0] === f);
    list.innerHTML = items.map(s => `<div class="ssx-s"><span class="fv" style="background:${s[5]};color:${ink(s[5])}">${s[4]}</span><span class="t"><span>${s[1]}</span><span class="h"> · ${s[2]}</span></span><span class="rel" data-tip="Relevance ${Math.round(s[3] * 100)}%"><i style="width:${s[3] * 100}%"></i></span><button class="ib" aria-label="Open source" data-tip="Open">${I('ext','xs')}</button></div>`).join('');
    stagger($$('.ssx-s', list), 40);
  }
  pill.onclick = () => { const open = box.classList.toggle('shut') === false; pill.setAttribute('aria-expanded', open); if (open) paint($('.ssx-fl .on', r).dataset.f); };
  $$('.ssx-fl .chip', r).forEach(ch => ch.onclick = () => { $$('.ssx-fl .chip', r).forEach(x => x.classList.toggle('on', x === ch)); paint(ch.dataset.f); });
  // the preview opens the sources once on its own, unless you take over first
  c.auto(1100, () => { if (pill.getAttribute('aria-expanded') === 'false') pill.click(); });
});
